import{z as A,x as p,o as t,c as B,q as i,j as r,D as E,d as e,s as o,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"拟合缩放律的方法","description":"","frontmatter":{"title":"拟合缩放律的方法","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/scaling-law-fitting.md","filePath":"llm/scaling-law-fitting.md","lastUpdated":1791413859000}'),C={name:"llm/scaling-law-fitting.md"};function m(d,a,h,D,f,c){const n=p("Mermaid");return t(),B("div",null,[a[2]||(a[2]=i('<h1 id="拟合缩放律的方法" tabindex="-1">拟合缩放律的方法 <a class="header-anchor" href="#拟合缩放律的方法" aria-label="Permalink to &quot;拟合缩放律的方法&quot;">​</a></h1><div class="epigraph"><p>幂律的指数对拟合窗口和脏点极其敏感；三种独立方法指向同一谷底，才配叫计算最优，而不是一条回归的自信区间。</p><footer>—— Kaplan et al., 2020；Hoffmann et al., Training Compute-Optimal Large Language Models, 2022 附录中的多种拟合法</footer></div><p><a href="/llm/multi-epoch-repetition">上一课</a>要求进入定律的是 \\(D_{\\mathrm{eff}}\\) 不是 \\(RU\\)。缺口是怎么把 \\(\\{N,D,L\\}\\) 收成可外推的曲线。主干 <a href="/llm/kaplan-scaling">Kaplan</a> 与 <a href="/llm/chinchilla">Chinchilla</a> 已经给出函数形式与「约 20 token / 参数」的读数，本课不重写那条政策建议，只写<strong>拟合卫生</strong>：窗口、三种独立法、不要把 warmup 与尖峰与 SDC 回滚吃进指数。后课的涌现争论依赖「你画的是哪一种横轴」；推理算力最优依赖「谷底是训练损失还是部署损失」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kaplan 用 \\(L(N)=E+(N_c/N)^{\\alpha_N}\\) 一类形式（另有 \\(D\\)、\\(C\\) 切片）。Hoffmann 指出：拟合假设、学习率日程、是否训满，会把等计算谷底从「偏大模型」推到「参数与数据近等比例」。同一家族的点，窗口若含压熵段，早期 \\(L\\) 高、斜率陡，外推会高估大模型收益。若含未收敛的短跑，会低估 \\(D\\) 的指数。Chinchilla 论文用三种方法交叉：参数化损失面再约束最优、固定 \\(C\\) 的直接比较、最后损失插值。一种方法给出的漂亮 \\(\\alpha\\) 不够。</p><p>对数空间的线性回归对横轴两端的点权重大。一个 SDC 回滚后少训 2% 却被当成完整 \\(D\\) 的点，会拧弯 \\(\\alpha\\)。阶段课要求先标注再拟合，本课把它收成硬步骤。<span class="marginnote">数字实例：「约 20 token / 参数」代入 70B 模型，就是约 \\(70\\times10^9 \\times 20 \\approx 1.4\\) 万亿 token 的训练数据。如果一次 SDC 回滚让实际只训了 98%（差约 280 亿 token），而这个点仍按 1.4T 记账，回归就会把这 2% 的缺口解释成「更大的模型更划算」——误差全被算进了指数。</span></p><p><span class="marginnote">\\(C\\approx 6ND\\) 对 MoE、对序列长度变化、对词表softmax 占比高的小模型都是近似。拟合前声明 FLOPs 计数器：只算 GEMM、还是含注意力二次项、是否含嵌入。计数器变了，\\(\\alpha\\) 不能与文献比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>步骤：</p><ol><li><strong>清洗。</strong> 去掉未结束 warmup 的点、明确失败的 NaN 跑、SDC 回滚且 token 缺口未补的点。尖峰后已恢复的跑可用终点，但不要用尖峰处的 \\(L\\)。</li><li><strong>单位。</strong> \\(D\\) 用 \\(D_{\\mathrm{eff}}\\)；\\(L\\) 用硬目标 CE 或 BPB，不混。</li><li><strong>切片。</strong> 先画 \\(L\\) vs \\(N\\)（\\(D\\) 充足）、\\(L\\) vs \\(D\\)（\\(N\\) 固定）、再画等 \\(C\\) 曲线。只看一条切片会重演 Kaplan vs Chinchilla 的误会。</li><li><strong>交叉。</strong> 至少两种：回归求约束最优，以及在相近 \\(C\\) 上直接比较若干 \\((N,D)\\)。两者谷底应同侧。</li><li><strong>留出。</strong> 最大模型不参与拟合，用来检验外推。没有留出的 \\(\\alpha\\) 只是描述统计。</li></ol><p>不要用下游准确率去拟合幂律再外推「涌现点」——那是下一课的陷阱。损失面拟合只用压缩指标。<span class="marginnote">常见误区：初学者容易以为拟合就是「把点连成一条线」。实际上在对数坐标里，改动横轴两端哪怕一个脏点，都会转动整条直线的斜率；而外推正是拿这条斜率去预测没训过的大模型，斜率差一点，几十亿美金的算力规划就跟着错——所以才要求三种方法交叉、留出最大点检验。</span></p><p>每一个点在进回归之前都要过一遍同一套检查：</p>',12)),(t(),r(s,null,{default:E(()=>[o(n,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%80%E4%B8%AA%E8%AE%AD%E7%BB%83%E7%82%B9%EF%BC%9AN%2C%20D%2C%20L%22%5D%20--%3E%20Q1%7B%22warmup%20%E5%B7%B2%E7%BB%93%E6%9D%9F%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20X%5B%22%E5%89%94%E9%99%A4%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20Q2%7B%22%E5%8F%96%E7%9A%84%E6%98%AF%E5%B0%96%E5%B3%B0%E5%A4%84%E7%9A%84%20L%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20X%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20Q3%7B%22SDC%20%E5%9B%9E%E6%BB%9A%E4%B8%94%20token%20%E7%BC%BA%E5%8F%A3%E6%9C%AA%E8%A1%A5%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20X%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20Q4%7B%22%E6%98%AF%E8%A7%84%E6%A8%A1%E6%9C%80%E5%A4%A7%E7%9A%84%E9%82%A3%E6%AC%A1%E8%B7%91%EF%BC%9F%22%7D%0A%20%20Q4%20--%3E%7C%22%E6%98%AF%22%7C%20H%5B%22%E7%95%99%E5%87%BA%EF%BC%9A%E5%8F%AA%E5%81%9A%E5%A4%96%E6%8E%A8%E6%A3%80%E9%AA%8C%22%5D%0A%20%20Q4%20--%3E%7C%22%E5%90%A6%22%7C%20F%5B%22%E8%BF%9B%E5%85%A5%E6%8B%9F%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>幂律是经验描述，在中间尺度成立，两端有不可约误差 \\(E\\) 与数据饱和。<span class="marginnote">术语翻译：幂律就是「规模翻一倍，损失就按固定比例下降」的规律，画在对数坐标上是一条直线；拟合指数 \\(\\alpha\\) 就是量这条直线的斜率。所谓外推，就是用小模型量出的斜率去猜大模型的损失——斜率差 0.01，预测就能差出可观的算力，所以拟合卫生才这么重要。</span>把 \\(E\\) 固定错，会把曲率赶进 \\(\\alpha\\)。Hoffmann 的参数化把 \\(E\\) 与两轴指数一起估，比先拍 \\(E\\) 更诚实，也更易过拟合——所以需要留出。等计算比较不依赖参数化形式，点少时更稳，但需要真的把各跑训到该 \\(C\\)，不能把「还在降」的点与「已平台」的点放在同一 \\(C\\) 上比。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不产出新的 20 token / 参数。换稳定件、换 MoE、换重复数据，\\(f(R)\\) 与 FLOPs 计数一变，谷底就动。下一课：即使损失光滑，下游指标仍可能看起来「突然」变好——先问是指标还是模型。</p>',4)),(t(),r(s,null,{default:E(()=>[o(n,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E8%B7%91%22%5D%20--%3E%20CLN%5B%22%E6%B8%85%E6%B4%97%E9%98%B6%E6%AE%B5%E4%B8%8E%E6%95%85%E9%9A%9C%E7%82%B9%22%5D%0A%20%20CLN%20--%3E%20SL%5B%22N%20%2F%20D%20%2F%20C%20%E5%88%87%E7%89%87%22%5D%0A%20%20SL%20--%3E%20REG%5B%22%E5%8F%82%E6%95%B0%E5%8C%96%E5%9B%9E%E5%BD%92%22%5D%0A%20%20SL%20--%3E%20ISO%5B%22%E7%AD%89%E8%AE%A1%E7%AE%97%E7%9B%B4%E6%8E%A5%E6%AF%94%22%5D%0A%20%20REG%20--%3E%20HOLD%5B%22%E6%9C%80%E5%A4%A7%E7%82%B9%E7%95%99%E5%87%BA%E6%A3%80%E9%AA%8C%22%5D%0A%20%20ISO%20--%3E%20HOLD%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l("h2",{id:"小结",tabindex:"-1"},[e("小结 "),l("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=l("ul",null,[l("li",null,"拟合前清洗 warmup、尖峰、SDC 缺口；用 \\(D_{\\mathrm{eff}}\\) 与声明过的 FLOPs 计数器。"),l("li",null,"三种切片交叉，谷底同侧才谈计算最优；留出最大点。"),l("li",null,"对数回归吃两端脏点；不要用下游准确率拟合 \\(\\alpha\\)。"),l("li",null,"形式是经验，稳定件与数据制度会移动谷底。"),l("li",null,"出处：Kaplan et al., 2020；Hoffmann et al., 2022。")],-1))])}const F=A(C,[["render",m]]);export{u as __pageData,F as default};
